        additionalProperties: false
      }
    }
  ];
}

function resolveSafe(p) {
  const root = DATA_DIR;
  const target = path.resolve(root, p);
  // Reject traversal: target must be within root
  if (target !== root && !target.startsWith(root + path.sep)) {
    throw new Error('Path traversal is not allowed');
  }
  return target;
}

export async function callTool(name, args = {}) {
  if (name !== 'file_metadata') {
    throw new Error('Unknown tool: ' + name);
  }
  const { path: rel } = args;
  if (typeof rel !== 'string' || rel.length === 0) {
    throw new Error('path is required');
  }
  // Reject absolute paths too
  if (path.isAbsolute(rel)) {
    throw new Error('Path must be relative to the data directory');
  }
  const full = resolveSafe(rel);
  let stat;
  try {
    stat = await fs.promises.stat(full);
  } catch (e) {
    throw new Error('File not found: ' + rel);
  }
  if (!stat.isFile()) {
    throw new Error('Not a file: ' + rel);
  }
  const ext = path.extname(rel).toLowerCase();
  const relPath = path.relative(DATA_DIR, full);
  const text = `path: ${relPath}\nsize: ${stat.size} bytes\nextension: ${ext}`;
  return {
    content: [{ type: 'text', text }]
  };
}
